const arClock = (x) => { try { const d = x instanceof Date ? x : new Date(x); return isNaN(d.getTime()) ? '' : d.toLocaleTimeString(NUM_LOCALE, { hour: '2-digit', minute: '2-digit' }); } catch { return ''; } };
