const lvDays = (from, to) => { const a = Date.parse(from + 'T12:00:00'), b = Date.parse(to + 'T12:00:00'); return (isNaN(a) || isNaN(b) || b < a) ? 0 : Math.round((b - a) / 86400000) + 1; };
