  const S = (k, ar, st, who, at, note) => ({ k, ar, st, who: who || '', at: at || '', note: note || '' });
  const out = [S('req', 'تقديم الطلب', 'done', r.requestedBy, r.at, r.reason)];
  const s1 = sd('leave'); if (s1) out.push(S('sign', 'توقيع الموظف على الطلب', s1.status === 'signed' ? 'done' : 'wait', s1.status === 'signed' ? r.employeeName : '', s1.signedAt));
  out.push(r.status === 'pending' ? S('dec', 'قرار الاعتماد', 'wait') : r.status === 'cancelled' ? S('dec', 'أُلغيت', 'stop', r.cancelledBy, r.cancelledAt)
    : S('dec', r.status === 'approved' ? 'الاعتماد' : 'الرفض', r.status === 'approved' ? 'done' : 'stop', r.decidedBy, r.decidedAt, r.note));
