  if ((ops.invoices || []).some(i => i.cur && i.cur !== 'SAR')) addAcc('5803', 'أرباح/خسائر فروق العملة (محقّقة)', 'exp', { link: 'سداد فواتير الموردين بالعملات الأجنبية بسعر يوم السداد' });
