      const lines = [];
      if (cash) lines.push(L(bCode, cash, 0));
      // v16.7: مع تفعيل وسيط الشبكة، الشبكة تدخل الوسيط (البنك يسوّيها لاحقاً) — التحويل البنكي المباشر يبقى للبنك
      if (card) lines.push(L(pcOn(c.date) ? posClrOf(bkCode) : bkCode, card, 0));
