const MQ = { navy: 'var(--mithqal-navy,#10294A)', gold: 'var(--mithqal-gold,#D9A83E)', white: 'var(--mithqal-white,#FFFFFF)', deep: 'var(--mithqal-deep-navy,#091A30)' };
