// v15.9: اشتقاق صلاحيات الكتابة من الدور — canPost=إدخال/ترحيل، canEdit=تعديل/حذف/تغيير إعدادات.
// (للأدوار القائمة: readOnly/postOnly غير معرّفين ⇒ canPost=canEdit=النطاق الكامل، بلا أي تغيير سلوك.)
const rolePost = (role) => ROLES[role]?.scope === 'all' && !ROLES[role]?.readOnly;
/* v47.1 — اعتماد القيد اليدوي (قرار المالك): يعتمده المحاسب أو المالك.
   قيد المالك (مسؤول النظام/الإدارة العليا) يُرحَّل مباشرة؛ قيد غيره ينتظر الاعتماد، ولا يعتمد أحدٌ قيدًا أدخله بنفسه.
   المرحّل فقط يدخل الدفاتر؛ المرفوض يبقى للأثر بسببه. */
const jeLive = (j) => !j || !j.status || j.status === 'posted';
const jeOwner = (me) => !!(ROLES[me?.role] || {}).admin;
/** v49.0 (قرار المالك G1): القيد الآلي (إقفال ضريبي، سداد، كشف بنك، تسوية الشبكة) يمر بالاعتماد كاليدوي — المالك وحده يُرحّله مباشرة */
const jeAutoSt = (me) => jeOwner(me) ? { status: 'posted', byId: me?.id || '', approvedBy: me?.name || '', approvedAt: nowISO() } : { status: 'pending', byId: me?.id || '' };
/** v49.0 (BUG-01-04): إقفال ضريبي أُلغي بقيد عكسي مرحّل لا يُعدّ إقفالًا — الإلغاء لا يحذف القيد المرحّل */
const vatCloseLive = (list, c) => !!c && c.status !== 'rejected' && !(list || []).some(j => j.vatUndo === c.id && jeLive(j));
/* ============================================================
   v49.5 — المرحلة 04 (MQ-059): مسارات اعتماد قابلة للتهيئة — مستويات بحدود مبالغ وأدوار
   org.wf = { po: { tiers: [{ id, min, roles:[...], label }] }, je: { tiers: [...] } }
   • المستند بقيمة X يحتاج كل مستوى حدّه ≤ X، بالترتيب. كل مستوى يعتمده دور من أدواره (أو المالك).
   • فصل المهام: المنشئ لا يعتمد، ولا يعتمد الشخص نفسه مستويين للمستند نفسه.
   • بلا تهيئة: السلوك الحالي كما هو (حد اعتماد أوامر الشراء الواحد، واعتماد واحد للقيد).
   ============================================================ */
const WF_DOCS = { po: { ar: 'أوامر الشراء', unit: 'إجمالي الأمر' }, je: { ar: 'القيود اليدوية', unit: 'مجموع المدين' } };
function wfTiers(org, type) {
  const T = ((((org || {}).wf || {})[type] || {}).tiers) || [];
  return T.filter(t => t && (t.roles || []).length && Number(t.min) >= 0).map((t, i) => ({ id: t.id || ('t' + i), min: Number(t.min) || 0, roles: t.roles, label: t.label || ('المستوى ' + (i + 1)) })).sort((a, b) => a.min - b.min);
}
const wfOn = (org, type) => wfTiers(org, type).length > 0;
const wfRequired = (org, type, amount) => wfTiers(org, type).filter(t => (Number(amount) || 0) >= t.min);
/** هل يحتاج أمر الشراء اعتمادًا؟ — المسار المهيّأ أولًا، وإلا حد الاعتماد القديم */
const poNeedsAppr = (org, total) => wfOn(org, 'po') ? wfRequired(org, 'po', total).length > 0 : ((Number(((org || {}).purchaseCfg || {}).approvalLimit) || 0) > 0 && total > Number(org.purchaseCfg.approvalLimit));
function wfState(org, type, doc, amount) {
  const req = wfRequired(org, type, amount), got = new Set(((doc || {}).approvals || []).map(a => a.tier));
  const next = req.find(t => !got.has(t.id)) || null;
  return { req, next, done: req.filter(t => got.has(t.id)), complete: !next, step: req.length ? req.indexOf(next) + 1 : 0 };
}
function wfCanAct(org, type, doc, amount, me) {
  if (!me) return { ok: false, why: 'لا مستخدم' };
  const S = wfState(org, type, doc, amount); if (!S.next) return { ok: false, why: 'اكتملت الاعتمادات' };
  const mine = (doc.byId && doc.byId === me.id) || (!doc.byId && doc.by && doc.by === me.name);
  if (mine) return { ok: false, why: 'لا تعتمد مستندًا أنشأته — فصل المهام' };
  if ((doc.approvals || []).some(a => (a.byId && a.byId === me.id) || a.by === me.name)) return { ok: false, why: 'اعتمدتَ مستوى سابقًا لهذا المستند — يعتمد المستوى التالي شخص آخر' };
  if (!(S.next.roles.includes(me.role) || (ROLES[me.role] || {}).admin)) return { ok: false, why: 'المستوى «' + S.next.label + '» يعتمده: ' + S.next.roles.map(r => (ROLES[r] || {}).ar || r).join('، ') };
  return { ok: true, tier: S.next, last: S.req.indexOf(S.next) === S.req.length - 1 };
}
const wfApprove = (doc, tier, me, at) => ({ ...doc, approvals: [...(doc.approvals || []), { tier: tier.id, label: tier.label, by: me.name || '', byId: me.id || '', role: me.role || '', at: at || nowISO() }] });
const canApproveJe = (me, j) => !!me && (jeOwner(me) || ['accountant', 'finance_department'].includes(me.role)) && (!j || (j.byId ? j.byId !== me.id : j.by !== me.name));
const isCostCtl = (me) => !!(ROLES[me?.role] || {}).costCtl;   // v37.8 مراقب التكاليف: يعتمد ويراقب ولا يُدخل حركات
// v27.1 — نطاق فروع المستخدم كما تعرضه الواجهة (myBranches): null = كل الفروع (المركز)، وإلا قائمة معرّفات.
// نطاق الكتابة (dataCtx.myBrIds) يجب أن يطابقه حرفيًا — أي سجل بفرع خارج هذا النطاق لا يُحفظ من جهاز الفرع.
const branchIdsOfUser = (u) => {
  if (!u) return [];
  const s = (ROLES[u.role] || ROLES.cashier).scope;
  if (s === 'all') return null;
  if (s === 'own') return u.branchId ? [u.branchId] : [];
  return u.allowedBranchIds || [];
};
// v27.1 — سجلات في next (بعد mutator) تقع خارج نطاق الفروع المسموح كتابته — على مسار الفرع تضيع بصمت إن لم تُرفض
function outOfScopeRecords(next, latest, myBrIds) {
  const seen = new Set();
  BR_COLS.forEach(c => ((latest || {})[c] || []).forEach(x => seen.add(c + ':' + x.id)));
  const out = [];
  BR_COLS.forEach(c => ((next || {})[c] || []).forEach(x => { if (!seen.has(c + ':' + x.id) && (!x.branchId || !(myBrIds || []).includes(x.branchId))) out.push({ col: c, id: x.id, branchId: x.branchId || '' }); }));
  return out;
}
const roleEdit = (role) => rolePost(role) && !ROLES[role]?.postOnly;
// v15.12: البوابة الأمنية المركزية — الحارس داخل عملية الحفظ نفسها (دفاع بعمق).
//   need='post' يتطلب صلاحية الإدخال، need='edit' يتطلب صلاحية التعديل/الإعدادات،
//   بلا need = بلا اشتراط (توافق خلفي كامل: كل الكتابات التشغيلية للكاشير/المدراء تمر كما كانت).
//   بهذا لا يُنفَّذ أي حفظ حسّاس دون فحص الصلاحية — حتى لو نسي زرٌّ ما فحصه.
const capOK = (role, need) => !need || (need === 'post' ? rolePost(role) : need === 'edit' ? roleEdit(role) : true);
/* v51.9 — صلاحيات التعديل الاختيارية لكل مستخدم (طلب المالك): يحددها المسؤول من «ظهور التطبيقات للمستخدمين ← صلاحيات التعديل».
   u.editPerms = { je: {mode, own, days}, inv: {...} } — mode: role (حسب الدور، الافتراضي) | allow (مسموح) | deny (ممنوع)
   own: ما أدخله هو فقط · days: خلال آخر N يومًا من تاريخ السجل (0 = بلا حد). المنح لمن يملك الإدخال أصلًا (rolePost) — لا يرفع صلاحية من لا يُدخل.
   الإدارة (admin) مسموح لها دائمًا. التحقق في الواجهة + في بوابة الحفظ المركزية (commit) + الحذف في قواعد الخادم (fin_*) عند «ممنوع». */
const EDIT_KINDS = { je: 'تعديل القيود اليدوية', inv: 'تعديل وحذف فواتير الموردين' };
function editPermOf(u, kind) { const p = ((u && u.editPerms) || {})[kind] || {}; return { mode: ['allow', 'deny'].includes(p.mode) ? p.mode : 'role', own: !!p.own, days: Math.max(0, Math.min(3650, parseInt(p.days, 10) || 0)) }; }
function canEditRec(u, kind, rec, td) {
  if (!u) return false;
  if ((ROLES[u.role] || {}).admin) return true;
  const p = editPermOf(u, kind);
  const base = p.mode === 'deny' ? false : p.mode === 'allow' ? rolePost(u.role) : roleEdit(u.role);
  if (!base || !rec) return base;
  if (p.own && !((rec.byId && rec.byId === u.id) || (rec.by && rec.by === u.name) || (rec.createdBy && rec.createdBy === u.name))) return false;
  if (p.days) { const d0 = String(rec.createdAt || rec.date || '').slice(0, 10); const t = td || today(); if (d0 && daysBetween(d0, t) > p.days) return false; }
  return true;
}

