  const rows = U.rows.filter(r => r.theo > 0); const theoV = sum(rows, r => r.theoV); if (!(theoV > 0)) return null;
  const flag = rows.filter(r => r.dq > 0 && (r.pct || 0) >= USAGE_MIN_PCT && r.dv >= USAGE_MIN_VAL).sort((a, b) => b.dv - a.dv);
