  const vat = Number((org.taxCfg || {}).rate) || 15, R = ((org.profitCfg || {}).cardRates) || {};
  const tidBr = {}; (org.cardTerminals || []).forEach(x => { if (x && x.tid) tidBr[String(x.tid)] = x.branchId; });
  const notes = [];
