    let cum = 0; const days = dates.map(d => { const e = anR(exp[d] || 0), k = anR(bank[anDay(d, lag)] || 0); cum = anR(cum + e - k); return { date: d, exp: e, bank: k, diff: anR(e - k), cum }; }).filter(x => x.exp || x.bank);
    const W = BL.filter(inW);
