    const open = lg.filter(l => l.status === 'open').sort((a, c) => String(a.at).localeCompare(String(c.at)));
    const done = y.filter(l => l.status === 'done');
    const hrs = (l) => (l.doneAt && l.at ? Math.max(0, (new Date(l.doneAt) - new Date(l.at)) / 36e5) : 0);
